import { describe, expect, test } from 'vitest'
import { contributionByEvent, profitabilityFigures, profitabilityLines } from '@/lib/growth/event-contribution'

/**
 * EVENT-LEVEL PROFITABILITY (D9x of Lawal's DemandOS directive of 30 October 2026, section 9: "Calculate the contribution
 * generated by native ticketing ... Compare contribution against direct campaign costs. Maintain separate reporting for
 * platform-wide audience acquisition and individual event campaigns. Do not claim profitability based on gross ticket
 * value."; the PROJECT MANAGER's 17:25: "contribution uses EventLinqs' real fee schedule, never the blueprint's A$2.50
 * example", so it reads the fee each order recorded).
 */
const order = (over: Partial<Parameters<typeof contributionByEvent>[0]['orders'][number]> = {}) => ({
  eventId: 'e1',
  status: 'confirmed',
  totalCents: 5_000,
  retainedCents: 300,
  processingCents: 100,
  refundedCents: 0,
  ...over,
})

describe('contribution per event', () => {
  test('is the fee kept less processing, never the ticket value', () => {
    const [e] = contributionByEvent({ orders: [order(), order()], spend: [] })
    expect(e).toMatchObject({ eventId: 'e1', orders: 2, contributionCents: 400, directSpendCents: 0, afterCampaignCents: 400 })
    expect(JSON.stringify(e)).not.toContain('5000')
  })
  test('a refund gives its share of the fee back and processing stays a cost', () => {
    const [e] = contributionByEvent({ orders: [order({ status: 'refunded', refundedCents: 5_000 })], spend: [] })
    expect(e.contributionCents).toBe(-100)
  })
  test('an order that records no fee is left out and counted, never guessed', () => {
    const [e] = contributionByEvent({ orders: [order(), order({ retainedCents: null })], spend: [] })
    expect(e).toMatchObject({ orders: 1, unrecorded: 1, contributionCents: 200 })
  })
  test('direct campaign cost comes off that event alone', () => {
    const out = contributionByEvent({
      orders: [order(), order({ eventId: 'e2' })],
      spend: [{ scope: 'event', eventId: 'e1', amountCents: 1_000 }],
    })
    expect(out.find((e) => e.eventId === 'e1')).toMatchObject({ directSpendCents: 1_000, afterCampaignCents: -800 })
    expect(out.find((e) => e.eventId === 'e2')).toMatchObject({ directSpendCents: 0, afterCampaignCents: 200 })
  })
  test('an event with spend and no sale still shows its loss', () => {
    expect(contributionByEvent({ orders: [], spend: [{ scope: 'event', eventId: 'e9', amountCents: 500 }] })).toEqual([
      { eventId: 'e9', orders: 0, unrecorded: 0, contributionCents: 0, directSpendCents: 500, afterCampaignCents: -500 },
    ])
  })
  test('a pending order earns nothing', () => {
    expect(contributionByEvent({ orders: [order({ status: 'pending' })], spend: [] })).toEqual([])
  })
})

describe('the words', () => {
  test('platform-wide acquisition is reported apart and never charged to a night', () => {
    const lines = profitabilityLines({
      events: contributionByEvent({ orders: [order()], spend: [] }),
      pooledSpendCents: 2_500,
    })
    expect(lines).toEqual(['Event campaigns: A$2.00 contribution, A$0.00 direct cost, A$2.00 after it', 'Platform acquisition, reported apart: A$25.00 spent'])
  })
})

describe('on /admin/today', () => {
  test('monthly measures: the event campaigns, and acquisition apart', () => {
    const figs = profitabilityFigures({ events: contributionByEvent({ orders: [order()], spend: [] }), pooledSpendCents: 0 })
    expect(figs.map((f) => [f.label, f.value, f.cadence, f.kind, f.display])).toEqual([
      ['Event campaigns, last 28 days', 200, 'monthly', 'measure', 'A$2.00 contribution, A$0.00 direct cost, A$2.00 after it'],
      ['Platform acquisition, last 28 days', 0, 'monthly', 'measure', 'A$0.00 spent, reported apart from any night'],
    ])
  })
  test('a night that lost money after its campaign asks for a person', () => {
    const figs = profitabilityFigures({ events: contributionByEvent({ orders: [], spend: [{ scope: 'event', eventId: 'e9', amountCents: 500 }] }), pooledSpendCents: 0 })
    expect(figs[0]).toMatchObject({ value: -500, asksForAPerson: true, kind: 'failed' })
    expect(figs[0].display).toContain('1 night lost money')
  })
})
